,"id":"85000000-0000-0013-0000-000000000001"},{"label":"B","text":"Hazrat Ayesha (RA)","is_correct":false,"id":"85000000-0000-0013-0000-000000000002"},{"label":"C","text":"Hazrat Sumayyah (RA)","is_correct":true,"id":"85000000-0000-0013-0000-000000000003"},{"label":"D","text":"Hazrat Fatimah (RA)","is_correct":false,"id":"85000000-0000-0013-0000-000000000004"}],"course_ids":["00000000-0000-0000-0000-000000000101","10000000-0000-0000-0000-000000000001"],"sourceKey":"who is recognized as the first female martyr of islam|","sources":["LC159-A25"],"source_label":"from LC-159","source_course":"PMA Long Course 159","source_type":"candidate-recalled experience","code":"PMA-LC-A-Q19"},{"id":"75000000-0000-0000-0000-000000000014","existing":true,"original_code":"PMA-Q-020","subject_id":"36b65a9a-2171-424e-99e2-e41e08d259cc","bank_key":"PMA-LC-A","stem":"A triangular prism has how many faces?","explanation":"A triangular prism has two triangular bases and three rectangular lateral faces, totaling five faces.","options":[{"label":"A","text":"4","is_correct":false,"id":"85000000-0000-0014-0000-000000000001"},{"label":"B","text":"5","is_correct":true,"id":"85000000-0000-0014-0000-000000000002"},{"label":"C","text":"6","is_correct":false,"id":"85000000-0000-0014-0000-000000000003"},{"label":"D","text":"8","is_correct":false,"id":"85000000-0000-0014-0000-000000000004"}],"course_ids":["00000000-0000-0000-0000-000000000101","10000000-0000-0000-0000-000000000001"],"sourceKey":"how many faces does a triangular prism have|","sources":["LC159-A26"],"source_label":"from LC-159","source_course":"PMA Long Course 159","source_type":"candidate-recalled experience","code":"PMA-LC-A-Q20"},{"id":"75000000-0000-0000-0000-000000000015","existing":true,"original_code":"PMA-Q-021","subject_id":"83e951c5-9e30-47c7-8848-a7c7f9abb484","bank_key":"PMA-LC-A","stem":"CPEC is a project between Pakistan and:","explanation":"CPEC stands for China-Pakistan Economic Corridor and is a bilateral Pakistan-China initiative.","options":[{"label":"A","text":"Turkey","is_correct":false,"id":"85000000-0000-0015-0000-000000000001"},{"label":"B","text":"China","is_correct":true,"id":"85000000-0000-0015-0000-000000000002"},{"label":"C","text":"Iran","is_correct":false,"id":"85000000-0000-0015-0000-000000000003"},{"label":"D","text":"Saudi Arabia","is_correct":false,"id":"85000000-0000-0015-0000-000000000004"}],"course_ids":["00000000-0000-0000-0000-000000000101","10000000-0000-0000-0000-000000000001"],"sourceKey":"cpec is an economic corridor between pakistan and which country|","sources":["LC159-A27"],"source_label":"from LC-159","source_course":"PMA Long Course 159","source_type":"candidate-recalled experience","code":"PMA-LC-A-Q21"},{"id":"87bac655-f8dd-42ef-b124-9e42d6ec7035","existing":false,"subject_id":"83e951c5-9e30-47c7-8848-a7c7f9abb484","bank_key":"PMA-LC-A","stem":"The Karakoram Highway is also known as which highway?","explanation":"The Karakoram Highway is also called the China–Pakistan Friendship Highway.","options":[{"label":"A","text":"Grand Trunk Road","is_correct":false},{"label":"B","text":"China–Pakistan Friendship Highway","is_correct":true},{"label":"C","text":"Indus Highway","is_correct":false},{"label":"D","text":"Makran Coastal Highway","is_correct":false}],"course_ids":["00000000-0000-0000-0000-000000000101","10000000-0000-0000-0000-000000000001"],"sourceKey":"the karakoram highway is also known as which highway|","sources":["LC159-A28"],"source_label":"from LC-159","source_course":"PMA Long Course 159","source_type":"candidate-recalled experience","code":"PMA-LC-A-Q1611"},{"id":"75000000-0000-0000-0000-000000000017","existing":true,"original_code":"PMA-Q-023","subject_id":"83e951c5-9e30-47c7-8848-a7c7f9abb484","bank_key":"PMA-LC-A","stem":"Khunjerab Pass connects Pakistan with:","explanation":"Khunjerab Pass is the high-altitude crossing linking Pakistan with China.","options":[{"label":"A","text":"Afghanistan","is_correct":false,"id":"85000000-0000-0017-0000-000000000001"},{"label":"B","text":"India","is_correct":false,"id":"85000000-0000-0017-0000-000000000002"},{"label":"C","text":"China","is_correct":true,"id":"85000000-0000-0017-0000-000000000003"},{"label":"D","text":"Iran","is_correct":false,"id":"85000000-0000-0017-0000-000000000004"}],"course_ids":["00000000-0000-0000-0000-000000000101","10000000-0000-0000-0000-000000000001"],"sourceKey":"khunjerab pass connects pakistan with which country|","sources":["LC159-A29"],"source_label":"from LC-159","source_course":"PMA Long Course 159","source_type":"candidate-recalled experience","code":"PMA-LC-A-Q23"},{"id":"75000000-0000-0000-0000-00000000066d","existing":true,"original_code":"PMA-Q-1645","subject_id":"83e951c5-9e30-47c7-8848-a7c7f9abb484","bank_key":"PMA-LC-A","stem":"Which pair of Pakistani individuals received Nobel Prizes in 1979 and 2014 respectively?","explanation":"Abdus Salam received the Physics prize in 1979, and Malala received the Peace prize in 2014.","options":[{"label":"A","text":"Abdus Salam and Malala Yousafzai","is_correct":true,"id":"85000000-0000-066d-0000-000000000001"},{"label":"B","text":"Abdul Qadeer Khan and Malala Yousafzai","is_correct":false,"id":"85000000-0000-066d-0000-000000000002"},{"label":"C","text":"Abdus Salam and Abdul Sattar Edhi","is_correct":false,"id":"85000000-0000-066d-0000-000000000003"},{"label":"D","text":"Allama Iqbal and Muhammad Ali Jinnah","is_correct":false,"id":"85000000-0000-066d-0000-000000000004"}],"course_ids":["00000000-0000-0000-0000-000000000101","10000000-0000-0000-0000-000000000001"],"sourceKey":"which pair consists of pakistani nobel prize laureates|","sources":["LC159-A30"],"source_label":"from LC-159","source_course":"PMA Long Course 159","source_type":"candidate-recalled experience","code":"PMA-LC-A-Q1591"},{"id":"75000000-0000-0000-0000-00000000001b","existing":true,"original_code":"PMA-Q-027","subject_id":"83e951c5-9e30-47c7-8848-a7c7f9abb484","bank_key":"PMA-LC-A","stem":"Hafeez Kardar was a famous Pakistani player of:","explanation":"Abdul Hafeez Kardar captained Pakistan's first Test-cricket team.","options":[{"label":"A","text":"Hockey","is_correct":false,"id":"85000000-0000-001b-0000-000000000001"},{"label":"B","text":"Cricket","is_correct":true,"id":"85000000-0000-001b-0000-000000000002"},{"label":"C","text":"Squash","is_correct":false,"id":"85000000-0000-001b-0000-000000000003"},{"label":"D","text":"Tennis","is_correct":false,"id":"85000000-0000-001b-0000-000000000004"}],"course_ids":["00000000-0000-0000-0000-000000000101","10000000-0000-0000-0000-000000000001"],"sourceKey":"abdul hafeez kardar was associated with which sport|","sources":["LC159-A31"],"source_label":"from LC-159","source_course":"PMA Long Course 159","source_type":"candidate-recalled experience","code":"PMA-LC-A-Q27"}]$import_data$::jsonb) LOOP
  qid:=(item->>'id')::uuid;
  INSERT INTO questions(id,code,bank_key,subject_id,difficulty,stem,explanation,time_limit_seconds,status,tags,source_label,source_course,source_type)
  VALUES(qid,item->>'code',item->>'bank_key',(item->>'subject_id')::uuid,'MEDIUM',item->>'stem',item->>'explanation',45,'APPROVED',ARRAY['20261009-import'],item->>'source_label',item->>'source_course',item->>'source_type') ON CONFLICT(id) DO NOTHING;
  SELECT coalesce(jsonb_agg(DISTINCT value),'[]') INTO refs FROM jsonb_array_elements((SELECT source_references FROM questions WHERE id=qid)||item->'sources');
  UPDATE questions SET stem=item->>'stem',explanation=item->>'explanation',source_references=refs,
   source_label=coalesce(item->>'source_label',source_label),source_course=coalesce(item->>'source_course',source_course),source_type=coalesce(item->>'source_type',source_type)
  WHERE id=qid AND (stem IS DISTINCT FROM item->>'stem' OR explanation IS DISTINCT FROM item->>'explanation' OR source_references IS DISTINCT FROM refs OR (item->>'source_label' IS NOT NULL AND source_label IS DISTINCT FROM item->>'source_label'));
  FOR opt IN SELECT value FROM jsonb_array_elements(item->'options') LOOP
   INSERT INTO question_options(question_id,option_key,label,text,is_correct,sort_order)
   VALUES(qid,'opt-'||lower(opt->>'label'),opt->>'label',opt->>'text',(opt->>'is_correct')::boolean,ascii(opt->>'label')-65)
   ON CONFLICT(question_id,label) DO UPDATE SET text=excluded.text,is_correct=excluded.is_correct WHERE question_options.text IS DISTINCT FROM excluded.text OR question_options.is_correct IS DISTINCT FROM excluded.is_correct;
  END LOOP;
  INSERT INTO question_courses(question_id,course_id) SELECT qid,value::uuid FROM jsonb_array_elements_text(item->'course_ids') ON CONFLICT DO NOTHING;
  IF (SELECT count(*) FROM question_options WHERE question_id=qid)<>4 OR (SELECT count(*) FROM question_options WHERE question_id=qid AND is_correct)<>1 OR (SELECT count(DISTINCT lower(trim(text))) FROM question_options WHERE question_id=qid)<>4 THEN RAISE EXCEPTION 'Import structure failed for %',qid; END IF;
 END LOOP;
END $apply$;
INSERT INTO question_courses(question_id,course_id) SELECT q.id,c.id FROM questions q CROSS JOIN courses c WHERE q.bank_key IN ('v','nv') AND c.code IN ('PMA_LONG_COURSE','PMA_LC','AFNS') ON CONFLICT DO NOTHING;
CREATE TRIGGER question_bank_code BEFORE INSERT OR UPDATE OF code,bank_key,subject_id ON questions FOR EACH ROW EXECUTE FUNCTION assign_question_bank_code();
NOTIFY pgrst,'reload schema';
COMMIT;
